#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    string s, t;
    cin >> n >> k >> s >> t;

    const long long NEG = -(1LL << 60);
    vector<vector<long long>> dp(k + 1, vector<long long>(n + 1, NEG));
    dp[0][0] = 0;

    for (char original : s) {
        vector<vector<long long>> next(k + 1, vector<long long>(n + 1, NEG));

        for (int used = 0; used <= k; ++used) {
            for (int count = 0; count <= n; ++count) {
                if (dp[used][count] == NEG) continue;

                char choices[3] = {original, t[0], t[1]};
                for (char chosen : choices) {
                    int newUsed = used + (chosen != original);
                    if (newUsed > k) continue;

                    int newCount = count + (chosen == t[0]);
                    long long value = dp[used][count];
                    if (chosen == t[1]) value += count;

                    next[newUsed][newCount] =
                        max(next[newUsed][newCount], value);
                }
            }
        }

        dp.swap(next);
    }

    long long answer = 0;
    for (int used = 0; used <= k; ++used)
        for (int count = 0; count <= n; ++count)
            answer = max(answer, dp[used][count]);

    cout << answer << '\n';
    return 0;
}

